UPDATE scholarships SET title = 'Chinese Government Scholarship (CSC) at Peking University (retired — duplicate of "Peking University CSC Scholarship", record 31)', coverage_type = 'Unspecified', amount_usd_value = 0, deadline = 'Duplicate record — use "Peking University CSC Scholarship" (record 31). CSC rounds close by home country (bilateral / Type A) or by host university (University Program / Type B); no single deadline is published.', description = 'This record is retired as a duplicate. It and "Peking University CSC Scholarship" (record 31) are two imports of the same thing — the Chinese Government Scholarship as held at Peking University — and both were re-verified on 2026-10-26 from the same China Scholarship Council application guide (campuschina.org): full tuition, free dormitory or accommodation subsidy, comprehensive medical insurance of CNY 800 a year (CNY 400 for programmes under six months) and a monthly stipend of CNY 2,500 (undergraduate), CNY 3,000 (master''s and general scholars) or CNY 3,500 (doctoral and senior scholars), with international airfare not included. Keeping two records for one host-university scheme only fragments the catalogue, so the records were consolidated in Pass 127: record 31 survives and now also carries the details first recorded here (the full bachelor''s-to-PhD level span and the Type A / Type B route distinction, including the warning that some Type B university awards are made without the CSC stipend). Apply through record 31; the scheme-wide record "Chinese Government Scholarship (CSC) — China Scholarship Council" describes the programme independently of any host university.', requirements = 'Duplicate record — do not use it to apply. See "Peking University CSC Scholarship" (record 31) for the consolidated eligibility, channels (bilateral / Type A via the home-country dispatching authority or Chinese embassy; University Program / Type B via Peking University as a designated university) and document list.', funding_type = 'Retired duplicate of record 31 (Peking University CSC Scholarship)', tuition_coverage = 'Duplicate record: the CSC package at Peking University (tuition, dormitory or accommodation subsidy, CNY 800/year medical insurance, monthly stipend CNY 2,500 / 3,000 / 3,500 by level) is recorded on record 31.', english_requirements = 'See record 31 (HSK 4 for Chinese-taught master''s/doctoral programmes, HSK 3 for Chinese-taught general/senior scholar programmes; host-programme language rules otherwise).', required_documents = '[]', deadline_date = NULL, deadline_type = 'not_published', rounds = '[]', expected_opening_period = NULL, expected_deadline_period = NULL, application_status = 'closed', last_verified_at = '2026-10-29 18:00:00+05', last_updated_at = '2026-10-29 18:00:00+05', notes = COALESCE(notes, '') || ' RETIRED in Pass 127 on 2026-10-29 as a duplicate of record 31 ("Peking University CSC Scholarship"): both rows record the Chinese Government Scholarship at Peking University and were re-verified from the same CSC guide on 2026-10-26. The survivor is record 31 (it carries the university source link and the cleaner side-table row); this row''s fuller verified details — the bachelor''s-to-PhD level span, the Type A/Type B distinction with the Type B stipend caveat, and the airfare exclusion — were merged into record 31 in the same pass. The welded university_scholarships row 379 at Peking University was deleted; the survivor''s row us 21 remains the single listing. Retain inactive; do not revive — edit record 31 instead.', is_active = false, award_amount = NULL, award_currency = NULL, award_period = NULL, award_basis = NULL WHERE id = 849;

